def _module(module, name):
    if _TYPE(module) is not types.ModuleType:
        raise Unobserved('nonordinary module')
    namespace = types.ModuleType.__getattribute__(module, '__dict__')
    if _TYPE(namespace) is not _DICT:
        raise Unobserved('module identity')
    if len(namespace) > 4096 or any(_TYPE(key) is not _STR for key in namespace):
        raise Unobserved('non-string or unbounded namespace')
    observed = namespace.get('__name__')
    if _TYPE(observed) is not _STR or observed != name:
        raise Unobserved('module identity')
    return namespace


def _name(value):
    if _TYPE(value) is _TYPE:
        namespace = type.__getattribute__(value, '__dict__')
        module = (type.__getattribute__(value, '__module__')
                  if _oneof(value, _BUILTIN_TYPES) else namespace.get('__module__', 'builtins'))
        qualname = type.__getattribute__(value, '__qualname__')
        if _TYPE(module) is not _STR or _TYPE(qualname) is not _STR:
            raise Unobserved('class name facts are not ordinary strings')
        return module, qualname
    raise Unobserved('not an ordinary class')


def _slot(value, name):
    cls = _TYPE(value)
    if _TYPE(cls) is not _TYPE:
        raise Unobserved('custom metaclass')
    descriptor = type.__getattribute__(cls, '__dict__').get(name)
    if (_TYPE(descriptor) is not types.MemberDescriptorType
            or descriptor.__objclass__ is not cls):
        raise Unobserved('not an original C slot')
    return descriptor.__get__(value, cls)


class _Encoder:
    def __init__(self):
        self.parts = []
        self.size = 0
        self.active = set()

    def raw(self, value):
        self.size += len(value)
        if self.size > _MAX_BYTES:
            raise Unobserved('facts exceed mechanical transport')
        self.parts.append(value)

    def scalar(self, tag, value):
        self.raw(tag + _PACK('<Q', len(value)) + value)

    def data(self, value, depth=0):
        if depth > 64:
            raise Unobserved('facts depth')
        t = _TYPE(value)
        if t is _NONE:
            self.raw(b'n'); return
        if t is _BOOL:
            self.raw(b't' if value else b'f'); return
        if t is _INT:
            if value.bit_length() > 128:
                raise Unobserved('unexpected metadata integer')
            self.scalar(b'i', str(value).encode('ascii')); return
        if t is _FLOAT:
            self.scalar(b'd', _PACK('<d', value)); return
        if t is _STR:
            self.scalar(b's', value.encode('utf-8', 'surrogatepass')); return
        if t is _BYTES:
            self.scalar(b'b', value); return
        if value is Ellipsis:
            self.raw(b'e'); return
        if t is _CODE:
            self.raw(b'c')
            # Semantic code fields are portable across wheel locations. The
            # project provider anchors separately retain the actual definition
            # code objects, including their nonsemantic source locations.
            for field in ('co_argcount', 'co_posonlyargcount', 'co_kwonlyargcount',
                          'co_nlocals', 'co_stacksize', 'co_flags', 'co_code',
                          'co_consts', 'co_names', 'co_varnames', 'co_freevars',
                          'co_cellvars', 'co_exceptiontable', 'co_name', 'co_qualname'):
                self.data(object.__getattribute__(value, field), depth + 1)
            return
        if _oneof(t, (_TUPLE, _LIST, _DICT, _SET, _FROZENSET)):
            identity = id(value)
            if identity in self.active or len(value) > 4096:
                raise Unobserved('cycle or oversized metadata container')
            self.active.add(identity)
            try:
                if t is _DICT:
                    if any(_TYPE(key) is not _STR for key in value):
                        raise Unobserved('non-string dictionary key')
                    self.raw(b'm' + _PACK('<Q', len(value)))
                    for key, item in value.items():
                        self.data(key, depth + 1); self.data(item, depth + 1)
                elif _oneof(t, (_SET, _FROZENSET)):
                    items = []
                    for item in value:
                        child = _Encoder(); child.data(item, depth + 1)
                        items.append(b''.join(child.parts))
                    self.raw((b'r' if t is _FROZENSET else b'q') + _PACK('<Q', len(items)))
                    for item in sorted(items):
                        self.scalar(b'v', item)
                else:
                    self.raw((b'a' if t is _LIST else b'u') + _PACK('<Q', len(value)))
                    for item in value:
                        self.data(item, depth + 1)
            finally:
                self.active.remove(identity)
            return
        if t is types.BuiltinFunctionType:
            self.raw(b'B'); self.data((value.__module__, value.__name__), depth + 1)
            return
        if _oneof(t, (types.GetSetDescriptorType, types.MemberDescriptorType,
                      types.MethodDescriptorType, types.WrapperDescriptorType)):
            self.raw(b'D'); self.data((t.__name__, value.__name__, _name(value.__objclass__)), depth + 1)
            return
        if t is _TYPE and any(value is item for item in _BUILTIN_TYPES):
            self.raw(b'T'); self.data(_name(value), depth + 1); return
        raise Unobserved('unsupported fact object')

    def function(self, value, namespace):
        if (_TYPE(value) is not _FUNCTION or value.__globals__ is not namespace
                or value.__closure__ is not None):
            raise Unobserved('function ownership')
        self.data((value.__code__, value.__defaults__, value.__kwdefaults__))
        globals_dict = value.__globals__
        builtins_dict = value.__builtins__
        if (_TYPE(builtins_dict) is not _DICT
                or any(_TYPE(key) is not _STR for key in builtins_dict)):
            raise Unobserved('function builtins ownership')
        for name in value.__code__.co_names:
            self.data(name)
            item = globals_dict.get(name, _MISSING)
            if item is _MISSING:
                item = builtins_dict.get(name, _MISSING)
            if item is _MISSING:
                self.raw(b'-')
            elif _TYPE(item) is _FUNCTION:
                self.raw(b'F'); self.data((item.__module__, item.__qualname__, item.__code__))
            elif _TYPE(item) is types.ModuleType:
                self.raw(b'M'); self.data(types.ModuleType.__getattribute__(item, '__dict__').get('__name__'))
            elif _TYPE(item) is types.MappingProxyType:
                # Each reachable intrinsic metadata map is checked below by
                # its definition-time anchor and its complete typed entries.
                self.raw(b'P')
            elif _TYPE(item) is _TYPE:
                if any(item is value for value in _BUILTIN_TYPES):
                    self.data(item)
                else:
                    self.raw(b'C'); self.ordinary_class(item)
            elif _TYPE(item) is _NONE or _oneof(_TYPE(item), (_BOOL, _INT, _FLOAT, _STR, _BYTES,
                                                        _TUPLE, _LIST, _DICT, _SET, _FROZENSET,
                                                        types.BuiltinFunctionType)):
                self.data(item)
            elif name in ('_default_encoder', '_FIELD'):
                # _default_encoder is not used by either fixed output shape.
                # _FIELD identity is separately checked for every dataclass field.
                self.raw(b'O'); self.data(_name(_TYPE(item)))
            else:
                raise Unobserved('unmodelled global dependency')

    def ordinary_class(self, cls):
        if _TYPE(cls) is not _TYPE:
            raise Unobserved('class metaprotocol')
        self.data(_name(cls))
        namespace = type.__getattribute__(cls, '__dict__')
        if any(_TYPE(key) is not _STR for key in namespace):
            raise Unobserved('class keys')
        for key, value in namespace.items():
            if key == '__dataclass_fields__':
                continue
            self.data(key)
            t = _TYPE(value)
            if t is _FUNCTION:
                self.data((value.__code__, value.__defaults__, value.__kwdefaults__))
            elif _oneof(t, (types.GetSetDescriptorType, types.MemberDescriptorType,
                            types.MethodDescriptorType, types.WrapperDescriptorType)):
                self.data((t.__name__, value.__name__, _name(value.__objclass__)))
            elif _oneof(t, (staticmethod, classmethod)):
                function = value.__func__
                self.data((t.__name__, function.__code__, function.__defaults__))
            elif key == '__dataclass_params__':
                if _TYPE(value).__module__ != 'dataclasses':
                    raise Unobserved('dataclass parameters')
                self.data(tuple(_slot(value, name) for name in ('init', 'repr', 'eq', 'order', 'unsafe_hash', 'frozen')))
            else:
                self.data(value)


def _json_facts(encoder, cli_namespace):
    module = cli_namespace.get('json')
    if module is not json:
        raise Unobserved('output JSON module replacement')
    namespace = _module(module, 'json')
    implementation = _module(json.encoder, 'json.encoder')
    encoder.function(namespace['dumps'], namespace)
    cls = namespace['JSONEncoder']
    if cls is not implementation.get('JSONEncoder'):
        raise Unobserved('encoder class split')
    encoder.ordinary_class(cls)
    class_namespace = type.__getattribute__(cls, '__dict__')
    for name in ('__init__', 'encode', 'iterencode', 'default'):
        encoder.function(class_namespace[name], implementation)
    encoder.function(implementation['_make_iterencode'], implementation)
    for name in ('encode_basestring', 'encode_basestring_ascii', 'c_make_encoder', 'INFINITY'):
        value = implementation[name]
        if name == 'c_make_encoder':
            if _TYPE(value) is not _TYPE or _name(value) != ('_json', 'Encoder'):
                raise Unobserved('nonordinary C encoder')
            encoder.ordinary_class(value)
        else:
            encoder.data(value)


def observation(action, cli, output, provider, opcode_module=None, *, diagnostics=None):
    """Return safe facts or None; never run any candidate provider/encoder.

    The HIA controller decides whether an exact digest is admitted. Replacement
    or nonordinary values are a foreign-route observation, not a CLI rejection.
    """
    if not _mechanics_unchanged():
        return None
    try:
        namespace = _module(cli, 'hepta.cli')
        definitions = namespace.get('_HIA_DISCOVERY_DEFINITIONS')
        if (_TYPE(definitions) is not _TUPLE or len(definitions) != 6
                or output is not definitions[1] or _TYPE(definitions[2]) is not _FUNCTION
                or _TYPE(output) is not _FUNCTION or output.__code__ is not definitions[4]):
            raise Unobserved('output definition anchor')
        if _GETTRACE() is not None or _GETPROFILE() is not None or _THREAD_COUNT() != 0:
            raise Unobserved('observable interpreter callbacks or threads')
        result = _Encoder()
        result.data(('hia.discovery.standard-provider-facts.v1', action,
                     sys.implementation.name, tuple(sys.version_info[:3])))
        result.function(output, namespace)
        _json_facts(result, namespace)
        if action == 1:
            if (provider is not definitions[0] or _TYPE(provider) is not _FUNCTION
                    or provider.__code__ is not definitions[3]):
                raise Unobserved('capabilities definition anchor')
            result.function(provider, namespace)
            result.data(namespace['HIA_AGENT_ACTIONS'])
        elif action == 2:
            op = _module(opcode_module, 'hepta.hia_opcodes')
            anchors = op.get('_HIA_DISCOVERY_DEFINITIONS')
            if (_TYPE(anchors) is not _TUPLE or len(anchors) != 8 or provider is not anchors[0]
                    or _TYPE(provider) is not _FUNCTION or provider.__code__ is not anchors[7]
                    or op.get('json') is not json):
                raise Unobserved('catalog definition anchor')
            result.function(provider, op)
            cls = anchors[1]
            if op.get('OpcodeSpec') is not cls:
                raise Unobserved('opcode class replacement')
            result.ordinary_class(cls)
            for index, name in enumerate(('OPCODES', 'PRIMITIVE_PROFILES', 'TYPES', '_GROUPS', 'TERMINATORS'), 2):
                if op.get(name) is not anchors[index]:
                    raise Unobserved('metadata object replacement')
            result.data(op['LATEST_CORE_SCHEMA'])
            result.data(op['TYPES'])
            for name in ('PRIMITIVE_PROFILES', '_GROUPS', 'TERMINATORS'):
                value = op[name]
                if _TYPE(value) is not types.MappingProxyType:
                    raise Unobserved('metadata map type')
                result.data(dict(value.items()))
            dc = _module(dataclasses, 'dataclasses')
            if op.get('asdict') is not dc['asdict']:
                raise Unobserved('asdict replacement')
            for name in ('asdict', '_asdict_inner', 'fields', '_is_dataclass_instance'):
                result.function(dc[name], dc)
            result.data(dc.get('_ATOMIC_TYPES'))
            fields = type.__getattribute__(cls, '__dict__').get('__dataclass_fields__')
            if _TYPE(fields) is not _DICT or any(_TYPE(key) is not _STR for key in fields):
                raise Unobserved('dataclass field map')
            names = []
            for name, field in fields.items():
                if _TYPE(field) is not dataclasses.Field or _slot(field, '_field_type') is not dc['_FIELD']:
                    raise Unobserved('dataclass field kind')
                actual = _slot(field, 'name')
                if _TYPE(actual) is not _STR or actual != name:
                    raise Unobserved('dataclass field name')
                names.append(name)
            result.data(tuple(names))
            values = op['OPCODES']
            if _TYPE(values) is not types.MappingProxyType:
                raise Unobserved('opcode table type')
            rows = []
            for key, spec in values.items():
                if _TYPE(key) is not _STR or _TYPE(spec) is not cls:
                    raise Unobserved('opcode record type')
                rows.append((key, tuple(_slot(spec, name) for name in names)))
            result.data(rows)
            result.data(op['sha256'])
        else:
            raise Unobserved('not a discovery action')
        raw = b''.join(result.parts)
        return raw, _sha256(raw).digest()
    except (Unobserved, KeyError, AttributeError, TypeError, ValueError, RuntimeError) as error:
        if diagnostics is not None:
            diagnostics.append((type(error).__name__, str(error)))
        return None

"""Optional discovery expressions; the original fifteen-action CLI stays live.

The companion HIA controller owns expression order, exact-fact admission,
native/foreign choice, error-object construction and terminal selection. Its
ports move actual Python callees and values; bytes are never a dict surrogate.
"""
from __future__ import annotations
import ctypes
from hashlib import sha256
import json
from pathlib import Path
import struct
import sys
import types

from .hia_cli_native import NativeCli, DOMAIN_ERRORS, _q, _print_parser_message
from .hia_cli_discovery_json_native import installed_cli_discovery_json
from .hia_cli_discovery_facts import observation
from .hia_json_preflight_native import NativeHiaJsonImage, _source_resource_path, _load_manifest

SOURCE_NAME='examples/hia_bootstrap/cli_discovery_routing.hepta'
SOURCE=_source_resource_path(SOURCE_NAME)
SCHEMA='hepta.hia.cli-discovery-routing-native.v1'
BUNDLE_SCHEMA='hepta.hia.cli-discovery-bundle.v2'
CONTEXT_BUNDLE_SCHEMA='hepta.hia.cli-discovery-bundle.v3'
MAGIC=int.from_bytes(b'HCLROUT1','little')
COMMAND=int.from_bytes(b'HCLCMD01','little')
_EMPTY=object()
_MISSING=object()
_UNKNOWN={}
_LITERALS=('ok','status','diagnostics','code','message','phase','error','E_DRIVER','driver',False)
_COMMON=('verify_program','read_bounded','decode_json','inspect_program','apply_program_patch','publish_program')


def _global(function, name):
    namespace=function.__globals__
    value=dict.get(namespace,name,_MISSING)
    if value is _MISSING and not dict.__contains__(namespace,name):
        value=dict.get(function.__builtins__,name,_MISSING)
        if value is _MISSING and not dict.__contains__(function.__builtins__,name):
            raise NameError("name '"+name+"' is not defined",name=name)
    return value


class DiscoveryExpression:
    def __init__(self, owner, parent):
        self.owner=owner
        self.parent=parent
        self.cli=parent.cli
        self.reference=types.ModuleType.__getattribute__(self.cli,'__dict__')['_HIA_DISCOVERY_DEFINITIONS'][2]
        self.nonce=parent.nonce
        self.action=_q(parent.workspace,16)
        self.workspace=ctypes.create_string_buffer(2048)
        self.output=ctypes.create_string_buffer(128)
        self.handles=[_EMPTY]
        self.pending=None
        self.busy=False
        self.finished=False
        self.domain_failure=False
        self.effect_failed=False
        self.retired=False
        self.unknown=False
        self.opcode_module=None
        self.output_handle=0
        self.provider_handle=0
        self.schema_handle=0
        self.claimed=None
        self.legacy_permission=None
        self.legacy_consumed=False
        self.route_events=[]
        self.packet=self._packet(0,0,0,0,self.action,_q(parent.raw,24))

    def register(self, value):
        self.handles.append(value)
        return len(self.handles)-1

    def value(self, handle):
        if type(handle) is not int or not 0<handle<len(self.handles) or self.handles[handle] is _EMPTY:
            raise RuntimeError('discovery handle is absent or consumed')
        return self.handles[handle]

    def take(self, handle):
        value=self.value(handle)
        self.handles[handle]=_EMPTY
        return value

    def _packet(self, command, sequence, operation, failed, a=0,b=0,c=0,d=0,
                digest=b'\0'*32, schema=b''):
        if type(digest) is not bytes or len(digest)!=32 or type(schema) is not bytes:
            raise RuntimeError('invalid discovery acknowledgement fields')
        return struct.pack('<10Q',MAGIC,command,self.nonce,sequence,operation,failed,a,b,c,d)+digest+struct.pack('<2Q',len(schema),0)+schema

    def _entry(self, packet):
        source=ctypes.create_string_buffer(packet,len(packet))
        result=self.owner.routing._entry(source,len(packet),self.output,len(self.output),self.workspace,len(self.workspace))
        if bytes(source.raw)!=packet:
            raise RuntimeError('discovery controller wrote to read-only input')
        return result,struct.unpack('<16Q',self.output.raw)

    def step(self):
        if self.busy or self.pending is not None or self.finished or self.unknown:
            self.finished=True
            raise RuntimeError('discovery continuation reentry or consumed step')
        self.busy=True
        try:
            code,words=self._entry(self.packet)
            if self.finished:
                raise RuntimeError('discovery step reentered its continuation')
            if words[0]!=COMMAND or any(words[9:]):
                raise RuntimeError('discovery command envelope refused')
            if code==2:
                if words[2] or words[8] not in (0,2,3,4):
                    raise RuntimeError('discovery terminal envelope refused')
                self.finished=True
                return code,words[8]
            if code!=1 or not 1<=words[2]<=21 or words[1]==0 or words[3] not in (0,1) or words[8]:
                raise RuntimeError('discovery effect envelope refused')
            self.pending=words[1:8]
            return code,0
        except BaseException:
            self.finished=True
            self.unknown=True
            _UNKNOWN[self.nonce]=self
            raise
        finally:
            self.busy=False

    def _pair(self, pending, observed):
        return self.register(pending),self.register(observed),0

    def _effect(self, operation,a,b,c,d):
        zero=(0,0,0)
        if operation==1:
            return self.parent._effect(35,0,0,0,0)
        if operation==2:
            from .hia_opcodes import opcode_catalog
            self.opcode_module=sys.modules[__package__+'.hia_opcodes']
            return self.register(opcode_catalog),0,0
        if operation==3:
            return self.register(_global(self.reference,'output_json')),0,0
        if operation==4:
            # The pending output callee is on the real operand stack while
            # the next LOAD_GLOBAL happens. A load error unwinds it there.
            return self._pair(self.take(a),_global(self.reference,'agent_capabilities'))
        if operation==5:
            return self._pair(self.take(a),self.parent.namespace.schema)
        if operation==6:
            self.output_handle,self.provider_handle,self.schema_handle=a,b,c
            value=observation(self.action,self.cli,self.value(a),self.value(b),self.opcode_module)
            schema=b''
            if self.action==2:
                actual=self.value(c)
                if type(actual) is not str:
                    return 0,0,0
                schema=actual.encode('utf-8','surrogatepass')
            if value is None or len(schema)>20:
                self.route_events.append('foreign-facts')
                return 0,0,0
            self.route_events.append('observed-standard-facts')
            return (1,0,0,value[1],schema)
        if operation==7:
            return self.register(_global(self.value(self.output_handle),'print')),0,0
        if operation==8:
            self.route_events.append('foreign-capabilities')
            self.take(a)(self.take(b)())
            return zero
        if operation==9:
            self.route_events.append('foreign-catalog')
            # The imported provider is a named local in the original frame.
            # Keep its separate owner until the handled exception unwinds.
            self.take(a)(self.value(b)(self.take(c)))
            return zero
        if operation==10:
            return self._legacy_port(1,a,b,c,d)
        if operation==11:
            return self._legacy_port(2,a,b,c,d)
        if operation==12:
            return self._legacy_port(22,a,b,c,d)
        if operation==13:
            return self._pair(self.take(a),_global(self.reference,'str'))
        if operation==14:
            # Carry the outer output callable on the actual operand stack
            # through str(error), including the latter's exceptional unwind.
            return self._pair(self.take(a),self.take(b)(self.value(c)))
        if operation==15:
            return self.register({}),0,0
        if operation==16:
            return self.register([]),0,0
        if operation==17:
            key=_LITERALS[b]
            if d==0:
                self.value(a)[key]=self.take(c)
            elif d==1:
                self.value(a)[key]=_LITERALS[c]
            else:
                raise RuntimeError('discovery literal operand tag')
            return zero
        if operation==18:
            self.value(a).append(self.take(b))
            return zero
        if operation==19:
            self.take(a)(self.take(b))
            return zero
        if operation==20:
            if type(a) is not int or not 0<a<len(self.handles):
                raise RuntimeError('discovery retirement handle outside its arena')
            if self.handles[a] is not _EMPTY:
                self.take(a)
            return zero
        if operation==21:
            if type(a) is not int or not 0<=a<len(_COMMON):
                raise RuntimeError('discovery named import index outside its arena')
            del self.parent.common[_COMMON[a]]
            return zero
        raise RuntimeError('unknown discovery effect')

    def _legacy_port(self,operation,a,b,c,d):
        if self.parent.discovery_permission is not None or self.legacy_permission is not None:
            self.finished=True
            raise RuntimeError('discovery shared port permission is already held')
        self.legacy_permission=(operation,a,b,c,d)
        self.legacy_consumed=False
        self.parent.discovery_permission=self
        try:
            result=self.parent._effect(operation,a,b,c,d)
            if not self.legacy_consumed or self.finished:
                raise RuntimeError('discovery shared port was not consumed exactly once')
            return result
        finally:
            self.parent.discovery_permission=None
            self.legacy_permission=None

    def consume_legacy_port(self,parent,operation,a,b,c,d):
        # This is the actual common CLI effect entry, under the separate new
        # image's claimed permission. The retained profile keeps its original
        # dict-returning ports. The new profile has explicit JSON-text/print
        # ports and never presents that text as an original Python dict.
        expected=10 if operation==1 else 11 if operation==2 else 12 if operation==22 else 0
        if (parent is not self.parent or parent.discovery_permission is not self
                or not self.busy or self.finished or self.legacy_consumed
                or self.legacy_permission!=(operation,a,b,c,d)
                or self.claimed is None or self.claimed[1]!=expected
                or _q(self.workspace,24)!=expected or _q(self.workspace,32)!=1):
            self.finished=True
            raise RuntimeError('discovery shared port lacks its actual HIA claim')
        self.legacy_consumed=True
        if operation==22:
            self.take(a)(self.take(b))
            return 0,0,0
        if operation==1:
            self.route_events.append('native-capabilities')
            raw=self.owner.discovery.capabilities_json()
        else:
            self.route_events.append('native-catalog')
            raw=self.owner.discovery.catalog_json(self.value(a).encode('utf-8','surrogatepass'))
        if not raw.endswith(b'\n'):
            raise RuntimeError('discovery JSON publication lacks its final newline')
        return self.register(raw[:-1].decode('utf-8')),0,0

    def observe(self):
        if self.pending is None or self.busy or self.finished or self.unknown:
            self.finished=True
            raise RuntimeError('discovery permission absent or reentered')
        sequence,operation,catching,a,b,c,d=self.pending
        self.pending=None
        self.busy=True
        self.domain_failure=False
        self.effect_failed=False
        try:
            code,words=self._entry(self._packet(2,sequence,operation,0))
            if code!=3 or words[:8]!=(COMMAND,sequence,operation,catching,a,b,c,d) or any(words[8:]):
                raise RuntimeError('discovery claim refused or acknowledgement lost')
            self.claimed=(sequence,operation,catching,a,b,c,d)
            try:
                result=self._effect(operation,a,b,c,d)
            except BaseException as error:
                self.effect_failed=True
                if isinstance(error,DOMAIN_ERRORS) and catching:
                    self.domain_failure=True
                    self.failed_command=(sequence,operation)
                raise
            if self.finished:
                raise RuntimeError('discovery effect reentered its continuation')
            if len(result)==5:
                x,y,z,digest,schema=result
                self.packet=self._packet(1,sequence,operation,0,x,y,z,digest=digest,schema=schema)
            else:
                self.packet=self._packet(1,sequence,operation,0,*result)
        finally:
            self.claimed=None
            self.busy=False

    def _drive(self):
        while True:
            code,result=self.step()
            if code==2:
                return result
            try:
                self.observe()
            except DOMAIN_ERRORS as error:
                if not self.domain_failure or self.finished:
                    raise
                self.domain_failure=False
                sequence,operation=self.failed_command
                self.packet=self._packet(1,sequence,operation,1,self.register(error))
                # Run the actual handler under the actual handled exception.
                try:
                    return self._drive()
                finally:
                    self._release_handled()

    def _release_handled(self):
        code,words=self._entry(self._packet(5,0,0,0))
        if code!=4 or words[0]!=COMMAND or any(words[9:]):
            self.unknown=True
            _UNKNOWN[self.nonce]=self
            raise RuntimeError('discovery handled exception release permission lost')
        if words[8]:
            self.take(words[8])

    def _retire(self):
        if self.retired or self.unknown:
            return
        self.finished=False
        self.pending=None
        self.packet=self._packet(4,0,0,0)
        try:
            result=self._drive()
            if _q(self.workspace,40)!=1 or any(value is not _EMPTY for value in self.handles[1:]):
                raise RuntimeError('discovery retirement left a foreign owner')
            self.retired=True
            self.opcode_module=None
        except BaseException:
            self.finished=True
            self.unknown=True
            _UNKNOWN[self.nonce]=self
            raise

    def __del__(self):
        if hasattr(self,'retired') and not self.retired and not self.unknown:
            try:self._retire()
            except BaseException:pass

    def run(self):
        try:
            result=self._drive()
        except BaseException:
            self.finished=True
            if self.effect_failed and not self.unknown:
                sequence,operation=self.failed_command if self.domain_failure else (_q(self.workspace,16),_q(self.workspace,24))
                try:
                    code,words=self._entry(self._packet(3,sequence,operation,0))
                    if code!=5 or _q(self.workspace,40)!=2:
                        raise RuntimeError('discovery known foreign error custody refused')
                except BaseException:
                    self.unknown=True
                    _UNKNOWN[self.nonce]=self
            else:
                self.unknown=True
                _UNKNOWN[self.nonce]=self
            raise
        self._retire()
        return result


class NativeDiscoveryCli(NativeCli):
    def __init__(self, base, discovery, routing, parser_context=None):
        super().__init__(base.control,base.formatter)
        self.discovery=discovery
        self.routing=routing
        self.parser_context=parser_context
        self.last_expression=None

    def run(self, argv, cli):
        session=self.prepare(argv,cli)
        if session.kind:
            first,second=self.format_result(session)
            session.finished=True
            if session.kind==3:
                if self.parser_context is not None:
                    self.parser_context.raise_error(session,first,second)
                _print_parser_message(first,sys.stderr)
                _print_parser_message(second,sys.stderr)
            else:
                _print_parser_message(first+second,sys.stdout)
            raise SystemExit(session.exit_code)
        expression=DiscoveryExpression(self,session)
        result=expression.run()
        self.last_expression={'events':tuple(expression.route_events),'nonce':expression.nonce}
        if result==3:
            return session.run()
        session.finished=True
        return result


def _child(path, relative, expected):
    if (type(relative) is not str or not relative or Path(relative).is_absolute()
            or '..' in Path(relative).parts or type(expected) is not str or len(expected)!=64):
        raise ValueError('invalid discovery bundle child identity')
    target=(path.parent/relative).resolve(strict=True)
    if not target.is_relative_to(path.parent):
        raise ValueError('discovery bundle child left its directory')
    raw=target.read_bytes()
    if len(raw)>16384 or sha256(raw).hexdigest()!=expected:
        raise ValueError('discovery bundle child bytes differ')
    return target,raw


def installed_bundle(path, raw, bundle, *, strict=False):
    from .hia_cli_native import SOURCES,CONTROL_SCHEMA,FORMAT_SCHEMA,_relative_path
    from .hia_json_preflight_native import _unique_manifest_pairs
    keys={'schema','control_manifest','control_manifest_sha256','format_manifest',
          'format_manifest_sha256','discovery_manifest','discovery_manifest_sha256',
          'routing_manifest','routing_manifest_sha256'}
    components=('control','format','discovery','routing')
    has_context=type(bundle) is dict and bundle.get('schema')==CONTEXT_BUNDLE_SCHEMA
    if has_context:
        keys|={'parser_context_manifest','parser_context_manifest_sha256'}
        components+=('parser_context',)
    if type(bundle) is not dict or set(bundle)!=keys or bundle['schema'] not in (BUNDLE_SCHEMA,CONTEXT_BUNDLE_SCHEMA):
        raise ValueError('invalid optional discovery CLI bundle')
    path=Path(path).resolve(strict=True)
    children={name:_child(path,bundle[name+'_manifest'],bundle[name+'_manifest_sha256'])
              for name in components}
    compilers=[];images={}
    for name,(child,child_raw) in children.items():
        metadata=json.JSONDecoder(object_pairs_hook=_unique_manifest_pairs).decode(child_raw.decode('utf-8'))
        if type(metadata) is not dict or not _relative_path(metadata.get('image_path')):
            raise ValueError('invalid discovery companion image path')
        compilers.append(metadata.get('compiler_sha256'))
        if strict:
            image=(child.parent/metadata['image_path']).resolve(strict=True)
            if not image.is_relative_to(child.parent):
                raise ValueError('discovery companion image leaves its component')
            with image.open('rb') as stream:image_raw=stream.read((1<<20)+1)
            if not 0<len(image_raw)<=1<<20 or sha256(image_raw).hexdigest()!=metadata.get('image_sha256'):
                raise ValueError('native CLI child image identity mismatch')
            images[name]=(image,image_raw)
    if any(value!=compilers[0] for value in compilers[1:]):
        raise ValueError('native discovery companion compilers differ')
    sources={name:source.read_bytes() for name,source in SOURCES.items()}
    control=_load_manifest(str(children['control'][0]),children['control'][1],sha256(sources['control']).hexdigest(),CONTROL_SCHEMA,NativeHiaJsonImage)
    formatter=_load_manifest(str(children['format'][0]),children['format'][1],sha256(sources['format']).hexdigest(),FORMAT_SCHEMA,NativeHiaJsonImage)
    base=NativeCli(control,formatter)
    discovery=installed_cli_discovery_json(str(children['discovery'][0]))
    source=SOURCE.read_bytes()
    routing=_load_manifest(str(children['routing'][0]),children['routing'][1],sha256(source).hexdigest(),SCHEMA,NativeHiaJsonImage)
    parser_context=None
    if has_context:
        from .hia_cli_parser_context_native import load_context_manifest,SOURCE as context_path
        context_source=context_path.read_bytes()
        parser_context=load_context_manifest(str(children['parser_context'][0]),children['parser_context'][1],sha256(context_source).hexdigest())
        if context_path.read_bytes()!=context_source:
            raise ValueError('parser context source changed during selection')
    if (path.read_bytes()!=raw or SOURCE.read_bytes()!=source
            or any(target.read_bytes()!=value for target,value in children.values())
            or any(SOURCES[name].read_bytes()!=value for name,value in sources.items())
            or any(target.read_bytes()!=value for target,value in images.values())):
        raise ValueError('optional discovery CLI changed while loading')
    return NativeDiscoveryCli(base,discovery,routing,parser_context)

"""Explicit HIA argv, presentation and fifteen-action CLI continuation.

The two immutable images own argument decisions, help/error bytes, action
sequencing, read budgets, report updates and exit selection. This foreign
adapter transports strings/handles and performs requested effects. Existing
semantic bodies, read_bounded policy, publication and successful pretty JSON
remain named foreign owners; this is not a whole-native CLI delivery claim.

The presentation profiles are ordinary English CPython 3.12.14, 3.14.4 and 3.14.10,
with the default 3.14 color theme. Arbitrary Python argument objects, custom
argparse subclasses/themes, and concurrent mutation of environment or streams
during parser construction are outside this explicit selected profile.
"""
from __future__ import annotations

import ctypes
from hashlib import sha256
import json
from itertools import count
import os
from pathlib import Path, PurePosixPath
import struct
import subprocess
import sys
from types import SimpleNamespace

from .hia_json_preflight_native import (
    NativeHiaJsonImage, _load_manifest, _source_resource_path, _unique_manifest_pairs,
)

SELECTOR = "HEPTA_HIA_CLI_MANIFEST"
SCHEMA = "hepta.hia.cli-native-bundle.v1"
CONTROL_SCHEMA = "hepta.hia.cli-control-native.v1"
FORMAT_SCHEMA = "hepta.hia.cli-format-native.v1"
SOURCES = {
    "control": _source_resource_path("examples/hia_bootstrap/cli_control.hepta"),
    "format": _source_resource_path("examples/hia_bootstrap/cli_format.hepta"),
}
ARGV_MAGIC = int.from_bytes(b"HCLIARG4", "little")
RESULT_MAGIC = int.from_bytes(b"HCLIRES4", "little")
STEP_MAGIC = int.from_bytes(b"HCLISTP4", "little")
COMMAND_MAGIC = int.from_bytes(b"HCLICMD4", "little")
CLAIM_MAGIC = int.from_bytes(b"HCLICLM5", "little")
ERROR_MAGIC = int.from_bytes(b"HCLIERR4", "little")
OBSERVE_MAGIC = int.from_bytes(b"HCLIOBS4", "little")
HIGH = 1 << 63
DOMAIN_ERRORS = (OSError, ValueError, UnicodeError, subprocess.SubprocessError)
_RELEASED = object()
# An interrupted continuation retains its actual foreign owners and native
# claim bytes. There is no implicit release, retry or quarantine-forget API.
_ACTIVE_SESSIONS = {}
_SESSION_NONCES = count(1)


def _session_nonce():
    # next() on this private integer counter is one fixed interpreter primitive.
    # A lost return consumes an identifier; neither close nor GC can reuse it.
    nonce = next(_SESSION_NONCES)
    if nonce >= 1 << 64:
        raise RuntimeError("native CLI instance nonce namespace exhausted")
    return nonce


def _utf32(value):
    if type(value) is not str:
        raise TypeError("selected native CLI requires ordinary string observations")
    return value.encode("utf-32-le", "surrogatepass")


def _text(raw):
    if len(raw) % 4:
        raise RuntimeError("misaligned native CLI text extent")
    try:
        return raw.decode("utf-32-le", "surrogatepass")
    except UnicodeError as error:
        raise RuntimeError("invalid native CLI Unicode observation") from error


def _q(buffer, offset):
    return struct.unpack_from("<Q", buffer, offset)[0]


def _frame(arguments, version, environment, profile, columns, color_terminal, ignore_environment, digit_limit):
    """Transport already observed strings and scalar runtime facts."""
    if type(arguments) is not list or any(type(arg) is not str for arg in arguments):
        raise TypeError("selected native CLI argv must contain ordinary strings")
    values = [version]
    presence = 1
    for index, name in enumerate(("PYTHON_COLORS", "NO_COLOR", "FORCE_COLOR", "TERM", "COLUMNS"), 1):
        value = environment.get(name)
        if value is not None:
            presence |= 1 << index
            values.append(value)
        else:
            values.append("")
    values += arguments
    payloads = [_utf32(value) for value in values]
    header_size = 192 + len(arguments) * 16
    raw = bytearray(header_size)
    struct.pack_into("<12Q", raw, 0, ARGV_MAGIC, 4, len(arguments), profile,
                     columns, int(ignore_environment), int(color_terminal), digit_limit,
                     0, presence, 0, 0)
    cursor = header_size
    for index, payload in enumerate(payloads):
        struct.pack_into("<2Q", raw, 96 + index * 16, cursor, len(payload) // 4)
        raw.extend(payload)
        cursor += len(payload)
    return bytes(raw)


def _runtime_profile():
    observed = tuple(sys.version_info[:3])
    profiles = {(3, 12, 14): 312, (3, 14, 4): 314, (3, 14, 10): 31410}
    if sys.implementation.name != "cpython" or observed not in profiles:
        raise RuntimeError("selected native CLI requires its pinned CPython 3.12.14, 3.14.4 or 3.14.10 profile")
    return profiles[observed]


def _terminal_columns():
    # Raw OS observation only. Native code parses COLUMNS and chooses fallback.
    try:
        value = os.get_terminal_size(sys.__stdout__.fileno()).columns
        return value
    except (AttributeError, OSError, ValueError):
        return 0


def _color_terminal():
    # Called only when the HIA color policy requests this observation.
    stream = sys.stdout
    if not hasattr(stream, "fileno"):
        return False
    try:
        return bool(os.isatty(stream.fileno()))
    except OSError:
        return bool(hasattr(stream, "isatty") and stream.isatty())


def _print_parser_message(message, stream):
    # Exact ordinary argparse._print_message write/refusal behavior.
    if message:
        stream = stream or sys.stderr
        try:
            stream.write(message)
        except (AttributeError, OSError):
            pass


def _publish_assembly(program, text, destination):
    """Explicit retained publication body, with the original effect order."""
    from .artifact_publication import publish_verified
    import tempfile
    target = Path(destination).absolute()
    if target.exists() or target.is_symlink():
        raise ValueError("Assembly output must be a new file")
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.parent.resolve() != target.parent:
        raise ValueError("Assembly output parent must not traverse a symlink")
    with tempfile.TemporaryDirectory(prefix=".hepta-assembly-", dir=target.parent) as temporary:
        stage = Path(temporary) / "program.hepta"
        payload = text.encode("utf-8")
        with stage.open("xb") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        receipt = publish_verified(stage, target, payload)
    return {"schema": "hepta.hia.assembly-output.v1", "ok": True,
            "output": str(target), "core_sha256": program.sha256,
            "publication": receipt, "deployment_authority": False}


class NativeCli:
    def __init__(self, control, formatter):
        self.control = control
        self.formatter = formatter

    def _format_call(self, raw, workspace):
        # This allocation scales with complete input and worst-case escapes;
        # it introduces no new independent CLI output-byte ceiling.
        capacity = (len(raw) // 4 * 12 + 32768) * 4
        output = ctypes.create_string_buffer(capacity)
        source = ctypes.create_string_buffer(raw, max(1, len(raw)))
        code = self.formatter._entry(source, len(raw), output, len(output),
                                     workspace, len(workspace))
        if code not in (0, 3):
            raise RuntimeError("native CLI formatter protocol or profile refused")
        count, split = struct.unpack_from("<2Q", workspace, 1024)
        if count > len(output) // 4 or split > count:
            raise RuntimeError("invalid native CLI formatter output extent")
        return code, ctypes.string_at(output, count * 4), split

    def _needs_color_terminal(self, raw):
        workspace = ctypes.create_string_buffer(131072)
        struct.pack_into("<Q", workspace, 0, OBSERVE_MAGIC)
        code, text, split = self._format_call(raw, workspace)
        request = _q(workspace, 1064)
        if code != 3 or text or split or request not in (0, 1):
            raise RuntimeError("invalid native CLI environment observation request")
        return request

    def prepare(self, argv, cli):
        # Iteration is performed once, as argparse.parse_known_args does.
        arguments = sys.argv[1:] if argv is None else list(argv)
        profile = _runtime_profile()
        environment = {name: os.environ.get(name) for name in
                       ("PYTHON_COLORS", "NO_COLOR", "FORCE_COLOR", "TERM", "COLUMNS")}
        version = "hia " + cli.__version__
        facts = dict(profile=profile, columns=80, color_terminal=False,
                     ignore_environment=bool(sys.flags.ignore_environment),
                     digit_limit=sys.get_int_max_str_digits())
        raw = _frame(arguments, version, environment, **facts)
        if self._needs_color_terminal(raw):
            facts["color_terminal"] = _color_terminal()
        facts["columns"] = _terminal_columns()
        return CliSession(self, _frame(arguments, version, environment, **facts), cli, arguments)

    def format_result(self, session):
        workspace = ctypes.create_string_buffer(131072 + session.argc * 24)
        ctypes.memmove(workspace, session.workspace, 1024)
        extras = _q(session.workspace, 80)
        if extras > session.argc:
            raise RuntimeError("invalid native CLI extra-argument extent")
        if extras:
            ctypes.memmove(ctypes.addressof(workspace) + 131072,
                           ctypes.addressof(session.workspace) + 32768 + session.argc * 48,
                           extras * 24)
        code, raw, split = self._format_call(session.raw, workspace)
        if code != 0:
            raise RuntimeError("unexpected native CLI formatter continuation")
        return _text(raw[:split * 4]), _text(raw[split * 4:])

    def driver_error(self, message):
        payload = _utf32(message)
        raw = struct.pack("<4Q", ERROR_MAGIC, 4, len(payload) // 4, 0) + payload
        workspace = ctypes.create_string_buffer(131072)
        code, text, split = self._format_call(raw, workspace)
        if code != 0 or split:
            raise RuntimeError("invalid native CLI E_DRIVER output")
        return _text(text)

    def run(self, argv, cli):
        session = self.prepare(argv, cli)
        if session.kind:
            first, second = self.format_result(session)
            session.finished = True
            if session.kind == 3:
                _print_parser_message(first, sys.stderr)
                _print_parser_message(second, sys.stderr)
            else:
                _print_parser_message(first + second, sys.stdout)
            raise SystemExit(session.exit_code)
        return session.run()


class CliSession:
    """A single native continuation; every foreign-effect permission is spent once."""
    def __init__(self, owner, raw, cli, arguments=None):
        self.owner, self.cli = owner, cli
        self.nonce = _session_nonce()
        bound = bytearray(raw)
        struct.pack_into("<Q", bound, 80, self.nonce)
        self.raw = raw = bytes(bound)
        # These are exact original ordinary-string argv observations. A full
        # native span returns the original object; partial spans use str slicing.
        self.arguments = None if arguments is None else tuple(arguments)
        self.argc = struct.unpack_from("<Q", raw, 16)[0]
        self.workspace = ctypes.create_string_buffer(65536 + self.argc * 80 + len(raw))
        self.output = ctypes.create_string_buffer(128)
        self.finished = False
        self.pending = False
        self.domain_failure = False
        self.in_effect = False
        self.cleanup_started = False
        self.terminal_handles = None
        self.discovery_permission = None
        self.handles = [_RELEASED]
        self.common = {}
        try:
            source = ctypes.create_string_buffer(raw, max(1, len(raw)))
            code = owner.control._entry(source, len(raw), self.output, len(self.output),
                                        self.workspace, len(self.workspace))
            if code != 0 or _q(self.workspace, 0) != RESULT_MAGIC:
                raise RuntimeError("native CLI argument frame or profile refused")
            self.kind = _q(self.workspace, 8)
            self.exit_code = _q(self.workspace, 112)
            if self.kind not in (0, 1, 2, 3) or self.exit_code not in (0, 2):
                raise RuntimeError("invalid native CLI argument result")
            self.namespace = self._namespace() if self.kind == 0 else None
            self.packet = self._packet(0, 0, 0, self.register(self.namespace), 0, 0)
        except BaseException:
            self.finished = True
            self.pending = False
            raise

    def _packet(self, sequence, operation, failed, a, b, c):
        return struct.pack("<12Q", STEP_MAGIC, 4, sequence, operation, failed,
                           a, b, c, 0, 0, 0, self.nonce)

    def take(self, handle):
        """Move exactly one HIA-designated owner onto the foreign call stack."""
        if (type(handle) is not int or not 0 < handle < len(self.handles)
                or self.handles[handle] is _RELEASED):
            raise RuntimeError("native CLI owner was already consumed or is invalid")
        # The tuple's first element holds the value during the slot clear.
        # This helper never stores it on the session or in a second pool.
        result, self.handles[handle] = self.handles[handle], _RELEASED
        return result

    def argument(self, handle, position):
        if self.consume_mask & (1 << position):
            return self.take(handle)
        return self.value(handle)

    def _fence(self):
        self.finished = True
        self.pending = False
        self.domain_failure = False

    def _release_terminal(self):
        if self.cleanup_started or self.terminal_handles is None:
            raise RuntimeError("native CLI terminal release is unavailable or consumed")
        # The native terminal transition consumed this release plan. Mark the
        # bridge before the first DECREF; reentry/lost ACK cannot repeat it.
        self.cleanup_started = True
        for handle in self.terminal_handles:
            self.take(handle)
        self.common.clear()
        self.namespace = None
        self.arguments = None
        # Namespace strings have no public object coercion in this explicit
        # profile. All remaining foreign values must have native custody.
        if any(value is not _RELEASED for value in self.handles[2:]):
            raise RuntimeError("native CLI terminal plan left a foreign owner")
        self.handles[1] = _RELEASED
        del _ACTIVE_SESSIONS[self.nonce]

    def register(self, value):
        handle = len(self.handles)
        if handle >= HIGH:
            raise RuntimeError("native CLI foreign handle namespace exhausted")
        self.handles.append(value)
        return handle

    def _literal(self, index):
        if index >= 512:
            raise RuntimeError("native CLI literal handle outside its arena")
        begin, size = struct.unpack_from("<2Q", self.workspace, 8192 + index * 16)
        if begin < 16384 or begin > 32768 or size > 32768 - begin:
            raise RuntimeError("native CLI literal extent outside its arena")
        return ctypes.string_at(ctypes.addressof(self.workspace) + begin, size).decode("ascii")

    def _input_text(self, begin, size):
        if begin % 4 or begin > len(self.raw) or size > (len(self.raw) - begin) // 4:
            raise RuntimeError("native CLI input-string extent outside its frame")
        if self.arguments is not None:
            for index, argument in enumerate(self.arguments):
                at, extent = struct.unpack_from("<2Q", self.raw, 192 + index * 16)
                if at <= begin and begin + size * 4 <= at + extent * 4:
                    start = (begin - at) // 4
                    return argument if start == 0 and size == extent else argument[start:start + size]
            raise RuntimeError("native CLI input span has no original argv owner")
        return _text(self.raw[begin:begin + size * 4])

    def _namespace(self):
        values = {}
        for index in range(19):
            kind, begin, size, key = struct.unpack_from("<4Q", self.workspace, 256 + index * 32)
            if kind == 0:
                continue
            name = self._literal(key)
            if name in values:
                raise RuntimeError("duplicate native CLI namespace field")
            if kind == 1:
                if begin or size:
                    raise RuntimeError("invalid native CLI None namespace record")
                value = None
            elif kind == 2:
                value = self._input_text(begin, size)
            elif kind == 3:
                if begin < 16384 or begin > 32768 or size > 32768 - begin:
                    raise RuntimeError("native CLI default-string extent outside its arena")
                value = ctypes.string_at(ctypes.addressof(self.workspace) + begin, size).decode("ascii")
            else:
                raise RuntimeError("unknown native CLI namespace record")
            values[name] = value
        return SimpleNamespace(**values)

    def value(self, handle):
        if 0 < handle < len(self.handles) and self.handles[handle] is not _RELEASED:
            return self.handles[handle]
        if HIGH <= handle < HIGH + 14:
            kind, a, size = struct.unpack_from("<3Q", self.workspace, 4096 + (handle - HIGH) * 32)
            if kind == 1 and a in (0, 1) and size == 0:
                return bool(a)
            if kind == 2 and 6144 <= a <= 8192 and size <= 8192 - a:
                return ctypes.string_at(ctypes.addressof(self.workspace) + a, size).decode("ascii")
        raise RuntimeError("unknown native CLI foreign or literal handle")

    def field(self, namespace, index):
        if index >= 19:
            raise RuntimeError("native CLI field index outside namespace")
        name = self._literal(_q(self.workspace, 256 + index * 32 + 24))
        return getattr(self.value(namespace), name)

    def step(self, packet=None):
        if self.finished or self.pending or self.domain_failure or self.in_effect:
            self.finished = True
            self.pending = False
            raise RuntimeError("native CLI continuation is closed or awaiting its effect")
        try:
            _ACTIVE_SESSIONS[self.nonce] = self
            raw = self.packet if packet is None else packet
            source = ctypes.create_string_buffer(raw, max(1, len(raw)))
            code = self.owner.control._entry(source, len(raw), self.output, len(self.output),
                                             self.workspace, len(self.workspace))
            command = struct.unpack_from("<16Q", self.output)
            if command[0] != COMMAND_MAGIC or any(command[10:]):
                raise RuntimeError("invalid native CLI command envelope")
            if code == 1:
                operation, sequence, catching, a, b, c, d = command[1:8]
                if (not 1 <= operation <= 44 or sequence == 0 or catching not in (0, 1)
                        or command[8] > 15 or command[9] != 0):
                    raise RuntimeError("invalid native CLI effect instruction")
                self.command = (operation, sequence, catching, a, b, c, d)
                self.consume_mask = command[8]
                self.pending = True
            elif code == 2:
                if command[1] or command[3] or command[4] not in (0, 1, 2) or any(command[5:8]):
                    raise RuntimeError("invalid native CLI terminal instruction")
                count, location = command[8:10]
                if count > 9 or location != 2816:
                    raise RuntimeError("invalid native CLI terminal owner plan")
                handles = struct.unpack_from("<" + "Q" * count, self.workspace, location)
                if (len(set(handles)) != len(handles)
                        or any(not 1 < handle < len(self.handles)
                               or self.handles[handle] is _RELEASED for handle in handles)):
                    raise RuntimeError("invalid native CLI terminal owner")
                self.terminal_handles = handles
                self.finished = True
                self.exit_code = command[4]
            else:
                raise RuntimeError("native CLI continuation protocol or profile refused")
            return code
        except BaseException:
            self.finished = True
            self.pending = False
            raise

    def _read_stack(self, pending, raw):
        """Return a still-live CALL argument and its subsequent read observation."""
        return self.register(pending), self.register(raw), 0

    def _effect(self, operation, a, b, c, d):
        if self.discovery_permission is not None:
            return self.discovery_permission.consume_legacy_port(self, operation, a, b, c, d)
        value, register, field, argument = self.value, self.register, self.field, self.argument
        zero = (0, 0, 0)
        if operation == 1:
            result = self.cli.agent_capabilities()
        elif operation == 2:
            from .hia_opcodes import opcode_catalog
            result = opcode_catalog(field(a, b))
        elif operation == 3:
            result = self.common["read_bounded"](field(a, b), limit=c)
        elif operation == 4:
            result = self.common["verify_program"](argument(a, 0))
        elif operation == 5:
            result = self.common["assemble_program"](value(a))
        elif operation == 6:
            result = self.common["diagnose_assembly"](value(a))
        elif operation == 7:
            result = self.common["render_assembly"](value(a))
        elif operation == 8:
            result = value(a).as_dict()
        elif operation == 9:
            result = value(a).report()
        elif operation == 10:
            result = self.common["inspect_program"](value(a))
        elif operation == 11:
            from .hia_program_native import build_program_machine
            result = build_program_machine(value(a), field(b, c), kind="object", linker="cc")
        elif operation == 12:
            result = self.common["decode_json"](argument(a, 0))
        elif operation == 13:
            revised, receipt = self.common["apply_program_patch"](value(a), argument(b, 1))
            return register(revised), register(receipt), 0
        elif operation == 14:
            revised, receipt, impact = self.common["analyze_patch_impact"](value(a), argument(b, 1))
            return register(revised), register(receipt), register(impact)
        elif operation == 15:
            result = self.common["prepare_edit"](
                value(a), function=field(b, 8), block=field(b, 9),
                output=field(b, 10), fields=argument(c, 2))
        elif operation == 16:
            revised, receipt = self.common["apply_edit"](value(a), argument(b, 1), argument(c, 2))
            return register(revised), register(receipt), 0
        elif operation == 17:
            result = self.common["prepare_batch"](value(a), argument(b, 1))
        elif operation == 18:
            revised, receipt = self.common["apply_batch"](value(a), argument(b, 1), argument(c, 2))
            return register(revised), register(receipt), 0
        elif operation == 19:
            result = self.common["publish_program"](value(a), field(b, c))
        elif operation == 20:
            result = self.cli.publish_json_view(value(a), field(b, c))
        elif operation == 21:
            result = _publish_assembly(value(a), value(b), field(c, d))
        elif operation == 22:
            self.cli.output_json(argument(a, 0))
            return zero
        elif operation == 23:
            print(value(a), end="")
            return zero
        elif operation == 24:
            result = {**argument(a, 0)}
        elif operation == 25:
            value(a)[value(b)] = argument(c, 2)
            return zero
        elif operation == 26:
            result = {}
        elif operation == 27:
            result = []
        elif operation == 28:
            value(a).append(argument(b, 1))
            return zero
        elif operation == 29:
            result = field(a, b)[c:c + d]
        elif operation == 30:
            return int(bool(value(a)["accepted"])), 0, 0
        elif operation == 31:
            return int(value(a).get("ok") is True), 0, 0
        elif operation == 32:
            result = str(value(a))
        elif operation == 33:
            result = self.owner.driver_error(value(a))
        elif operation == 34:
            print(argument(a, 0))
            return zero
        elif operation == 35:
            from .hia_program import verify_program
            from .hia_program_tools import (
                read_bounded, decode_json, inspect_program, apply_program_patch, publish_program,
            )
            self.common.update(verify_program=verify_program, read_bounded=read_bounded,
                               decode_json=decode_json, inspect_program=inspect_program,
                               apply_program_patch=apply_program_patch, publish_program=publish_program)
            return zero
        elif operation == 36:
            from .hia_agent_assembly import assemble_program, render_assembly, diagnose_assembly
            self.common.update(assemble_program=assemble_program, render_assembly=render_assembly,
                               diagnose_assembly=diagnose_assembly)
            return zero
        elif operation == 37:
            from .hia_edit_query import prepare_edit
            self.common["prepare_edit"] = prepare_edit
            return zero
        elif operation == 38:
            from .hia_edit_query import apply_edit, MAX_RESPONSE_BYTES
            self.common["apply_edit"] = apply_edit
            return zero
        elif operation == 39:
            from .hia_edit_batch import prepare_batch
            self.common["prepare_batch"] = prepare_batch
            return zero
        elif operation == 40:
            from .hia_edit_batch import apply_batch, MAX_QUERY_BYTES, MAX_RESPONSE_BYTES
            self.common["apply_batch"] = apply_batch
            return zero
        elif operation == 41:
            from .hia_patch_impact import analyze_patch_impact
            self.common["analyze_patch_impact"] = analyze_patch_impact
            return zero
        elif operation == 42:
            from .hia_program_selfhost import build_program_selfhost
            result = build_program_selfhost(value(a), field(b, c),
                manifest=field(b, 17), manifest_sha256=field(b, 18),
                kind=field(b, 5), target=field(b, 6))
        elif operation == 43:
            argument(a, 0)
            argument(b, 1)
            return zero
        elif operation == 44:
            # pending is evaluated onto the real CALL stack before the read.
            # A read exception releases it during stack unwind, before entering
            # the CLI except handler, exactly like the original nested call.
            return self._read_stack(argument(a, 0),
                self.common["read_bounded"](field(b, c), limit=d))
        else:
            raise RuntimeError("unknown native CLI effect")
        return register(result), 0, 0

    def _claim_effect(self):
        operation, sequence, catching, a, b, c, d = self.command
        raw = struct.pack("<12Q", CLAIM_MAGIC, 4, sequence, operation,
                          self.nonce, 0, 0, 0, 0, 0, 0, 0)
        source = ctypes.create_string_buffer(raw, len(raw))
        code = self.owner.control._entry(source, len(raw), self.output, len(self.output),
                                         self.workspace, len(self.workspace))
        expected = (COMMAND_MAGIC, operation, sequence, catching, a, b, c, d,
                    self.consume_mask, 0, 0, 0, 0, 0, 0, 0)
        if code != 3 or struct.unpack_from("<16Q", self.output) != expected:
            raise RuntimeError("native CLI effect claim refused or lost")

    def observe(self):
        if self.finished or not self.pending or self.in_effect:
            self.finished = True
            self.pending = False
            raise RuntimeError("native CLI effect permission already consumed or closed")
        operation, sequence, catching, a, b, c, d = self.command
        self.pending = False
        self.domain_failure = False
        self.in_effect = True
        try:
            self._claim_effect()
            try:
                result = self._effect(operation, a, b, c, d)
            except DOMAIN_ERRORS:
                if catching:
                    self.domain_failure = True
                else:
                    self.finished = True
                raise
            if self.finished:
                raise RuntimeError("native CLI effect reentered a fenced continuation")
            self.packet = self._packet(sequence, operation, 0, *result)
            self.in_effect = False
            return self.packet
        except BaseException:
            self.in_effect = False
            if not self.domain_failure:
                self.finished = True
                self.pending = False
            raise

    def _drive(self):
        while self.step() == 1:
            try:
                self.observe()
            except DOMAIN_ERRORS as error:
                if not self.domain_failure or self.finished:
                    raise
                self.domain_failure = False
                operation, sequence, catching, a, b, c, d = self.command
                self.packet = self._packet(sequence, operation, 1, self.register(error), 0, 0)
                # The entire native-requested handler runs inside this except.
                # str(error) and stdout effects retain the real active exception;
                # no synthetic raise alters its traceback or context.
                return self._drive()
        return self.exit_code

    def run(self):
        try:
            result = self._drive()
            # _drive's real except has unwound before local owners are released.
            self._release_terminal()
            return result
        except BaseException:
            self._fence()
            raise


def _relative_path(value):
    return (type(value) is str and bool(value) and "\0" not in value and "\\" not in value
            and not value.startswith("/") and str(PurePosixPath(value)) == value
            and all(part not in ("", ".", "..") for part in value.split("/")))


def installed_cli(manifest_path):
    """Bind both sources and exact child manifests; selected failures never fall back.

    Warm cache entries retain their original immutable image mapping. They
    do not reread a previously admitted disk image on every command. Source
    and manifest bytes are rebound on every explicit selection.
    """
    path = Path(manifest_path).resolve(strict=True)
    with path.open("rb") as stream:
        raw = stream.read(8193)
    if len(raw) > 8192:
        raise ValueError("native CLI bundle exceeds manifest extent")
    bundle = json.JSONDecoder(object_pairs_hook=_unique_manifest_pairs).decode(raw.decode("utf-8"))
    if type(bundle) is dict and bundle.get("schema") in ("hepta.hia.cli-discovery-bundle.v2", "hepta.hia.cli-discovery-bundle.v3"):
        from .hia_cli_discovery_routing_native import installed_bundle
        return installed_bundle(path, raw, bundle)
    keys = {"schema", "control_manifest", "control_manifest_sha256",
            "format_manifest", "format_manifest_sha256"}
    if type(bundle) is not dict or set(bundle) != keys or bundle["schema"] != SCHEMA:
        raise ValueError("invalid native CLI bundle")
    children = {}
    compilers = []
    for name in ("control", "format"):
        relative, expected = bundle[name + "_manifest"], bundle[name + "_manifest_sha256"]
        if (not _relative_path(relative) or type(expected) is not str or len(expected) != 64
                or any(char not in "0123456789abcdef" for char in expected)):
            raise ValueError("invalid native CLI child identity")
        child = (path.parent / relative).resolve(strict=True)
        if not child.is_relative_to(path.parent):
            raise ValueError("native CLI child leaves its bundle")
        with child.open("rb") as stream:
            child_raw = stream.read(16385)
        if len(child_raw) > 16384 or sha256(child_raw).hexdigest() != expected:
            raise ValueError("native CLI child manifest identity mismatch")
        metadata = json.JSONDecoder(object_pairs_hook=_unique_manifest_pairs).decode(child_raw.decode("utf-8"))
        if type(metadata) is not dict or not _relative_path(metadata.get("image_path")):
            raise ValueError("invalid native CLI child image path")
        compilers.append(metadata.get("compiler_sha256"))
        children[name] = (child, child_raw)
    if compilers[0] != compilers[1]:
        raise ValueError("native CLI companion compilers differ")
    source_hashes = {name: sha256(source.read_bytes()).hexdigest() for name, source in SOURCES.items()}
    control = _load_manifest(str(children["control"][0]), children["control"][1],
                             source_hashes["control"], CONTROL_SCHEMA, NativeHiaJsonImage)
    formatter = _load_manifest(str(children["format"][0]), children["format"][1],
                               source_hashes["format"], FORMAT_SCHEMA, NativeHiaJsonImage)
    if (path.read_bytes() != raw
            or any(child.read_bytes() != child_raw for child, child_raw in children.values())
            or any(sha256(source.read_bytes()).hexdigest() != source_hashes[name]
                   for name, source in SOURCES.items())):
        raise ValueError("native CLI selection changed while loading")
    return NativeCli(control, formatter)


def installed_cli_strict(manifest_path):
    """Bind both sources and exact child manifests; selected failures never fall back.

    Warm cache entries retain immutable mappings. Both image files, source
    resources and manifests are freshly read and rebound on each selection;
    changing a selected disk input never silently substitutes cached bytes.
    """
    path = Path(manifest_path).resolve(strict=True)
    with path.open("rb") as stream:
        raw = stream.read(8193)
    if len(raw) > 8192:
        raise ValueError("native CLI bundle exceeds manifest extent")
    bundle = json.JSONDecoder(object_pairs_hook=_unique_manifest_pairs).decode(raw.decode("utf-8"))
    if type(bundle) is dict and bundle.get("schema") in ("hepta.hia.cli-discovery-bundle.v2", "hepta.hia.cli-discovery-bundle.v3"):
        from .hia_cli_discovery_routing_native import installed_bundle
        return installed_bundle(path, raw, bundle, strict=True)
    keys = {"schema", "control_manifest", "control_manifest_sha256",
            "format_manifest", "format_manifest_sha256"}
    if type(bundle) is not dict or set(bundle) != keys or bundle["schema"] != SCHEMA:
        raise ValueError("invalid native CLI bundle")
    children = {}
    images = {}
    compilers = []
    for name in ("control", "format"):
        relative, expected = bundle[name + "_manifest"], bundle[name + "_manifest_sha256"]
        if (not _relative_path(relative) or type(expected) is not str or len(expected) != 64
                or any(char not in "0123456789abcdef" for char in expected)):
            raise ValueError("invalid native CLI child identity")
        child = (path.parent / relative).resolve(strict=True)
        if not child.is_relative_to(path.parent):
            raise ValueError("native CLI child leaves its bundle")
        with child.open("rb") as stream:
            child_raw = stream.read(16385)
        if len(child_raw) > 16384 or sha256(child_raw).hexdigest() != expected:
            raise ValueError("native CLI child manifest identity mismatch")
        metadata = json.JSONDecoder(object_pairs_hook=_unique_manifest_pairs).decode(child_raw.decode("utf-8"))
        if type(metadata) is not dict or not _relative_path(metadata.get("image_path")):
            raise ValueError("invalid native CLI child image path")
        image_path = (child.parent / metadata["image_path"]).resolve(strict=True)
        if not image_path.is_relative_to(child.parent):
            raise ValueError("native CLI child image leaves its component")
        with image_path.open("rb") as stream:
            image_raw = stream.read((1 << 20) + 1)
        if (not 0 < len(image_raw) <= 1 << 20
                or sha256(image_raw).hexdigest() != metadata.get("image_sha256")):
            raise ValueError("native CLI child image identity mismatch")
        images[name] = (image_path, image_raw)
        compilers.append(metadata.get("compiler_sha256"))
        children[name] = (child, child_raw)
    if compilers[0] != compilers[1]:
        raise ValueError("native CLI companion compilers differ")
    source_hashes = {name: sha256(source.read_bytes()).hexdigest() for name, source in SOURCES.items()}
    control = _load_manifest(str(children["control"][0]), children["control"][1],
                             source_hashes["control"], CONTROL_SCHEMA, NativeHiaJsonImage)
    formatter = _load_manifest(str(children["format"][0]), children["format"][1],
                               source_hashes["format"], FORMAT_SCHEMA, NativeHiaJsonImage)
    if (path.read_bytes() != raw
            or any(child.read_bytes() != child_raw for child, child_raw in children.values())
            or any(image.read_bytes() != raw_image for image, raw_image in images.values())
            or any(sha256(source.read_bytes()).hexdigest() != source_hashes[name]
                   for name, source in SOURCES.items())):
        raise ValueError("native CLI selection changed while loading")
    return NativeCli(control, formatter)

"""Fixed CPython object-layout ports for an explicitly admitted parser graph.

No parser constructor, argument scanner, action body, or retained CLI body is
executed here. The HIA image owns all allocation/link/release instructions.
Definition fingerprints are admission data, not executable Python payloads.
"""
from __future__ import annotations

import argparse
from hashlib import sha256
import re
import struct
import sys
import types

_TYPE = type
_OBJECT = object
_DICT = dict
_TUPLE = tuple
_LIST = list
_STR = str
_BYTES = bytes
_INT = int
_BOOL = bool
_FUNCTION = types.FunctionType
_CODE = types.CodeType
_EMPTY = object()


def _definition(value):
    """Encode exact built-in layout facts without coercion or user lookup."""
    t = _TYPE(value)
    if value is None:
        return b'n'
    if value is Ellipsis:
        return b'e'
    if t is _BOOL:
        return b't' if value else b'f'
    if t is _INT:
        return b'i' + _STR(value).encode('ascii') + b';'
    if t is float:
        return b'd' + struct.pack('<d', value)
    if t is _STR:
        raw = _STR.encode(value, 'utf-8', 'surrogatepass')
        return b's' + struct.pack('<Q', len(raw)) + raw
    if t is _BYTES:
        return b'b' + struct.pack('<Q', len(value)) + value
    if t is _TUPLE:
        return b'(' + b''.join(_definition(item) for item in value) + b')'
    if t is _LIST:
        return b'[' + b''.join(_definition(item) for item in value) + b']'
    if t is frozenset:
        return b'<' + b''.join(sorted(_definition(item) for item in value)) + b'>'
    if t is _CODE:
        return b'c' + _definition((value.co_argcount, value.co_posonlyargcount,
            value.co_kwonlyargcount, value.co_nlocals, value.co_flags, value.co_code,
            value.co_consts, value.co_names, value.co_varnames, value.co_freevars,
            value.co_cellvars, value.co_exceptiontable))
    if t is _FUNCTION:
        return b'F' + _definition((value.__module__, value.__name__, value.__qualname__,
                                   value.__code__, value.__defaults__))
    if t is _TYPE:
        namespace = _TYPE.__getattribute__(value, '__dict__')
        methods = []
        for name, item in namespace.items():
            if _TYPE(item) is _FUNCTION:
                methods.append((name, _definition(item)))
            elif _TYPE(item) in (staticmethod, classmethod):
                methods.append((name, _definition(item.__func__)))
            elif _TYPE(item) is property:
                methods.append((name, _definition((item.fget, item.fset, item.fdel))))
        return b'T' + _definition((_TYPE.__getattribute__(value, '__module__'),
            _TYPE.__getattribute__(value, '__qualname__'), _TUPLE(methods)))
    raise ValueError('unsupported physical definition fingerprint type')


def definition_sha(value):
    return sha256(_definition(value)).hexdigest()


def _parser_type():
    # An explicit selected-native test may poison the public constructor name.
    # Locate the genuine, still-live built-in-metaclass type, but never invoke
    # its __init__ or a cached constructor. Its entire layout is fingerprinted.
    matches = []
    for value in _TYPE.__subclasses__(argparse._ActionsContainer):
        if (_TYPE(value) is _TYPE
                and _TYPE.__getattribute__(value, '__module__') == 'argparse'
                and _TYPE.__getattribute__(value, '__qualname__') == 'ArgumentParser'):
            matches.append(value)
    if len(matches) != 1:
        raise ValueError('ambiguous physical ArgumentParser type')
    return matches[0]


def shared_objects(cli, paths, signatures):
    from . import hia_schema
    modules = {'argparse': argparse, 'cli': cli, 'schema': hia_schema}
    if '_colorize' in sys.modules:
        modules['_colorize'] = sys.modules['_colorize']
    result = []
    parser_type = _parser_type()
    for path, signature in zip(paths, signatures, strict=True):
        value = _EMPTY
        for operation, operand in path:
            if operation == 'module-item':
                module, name = operand
                namespace = types.ModuleType.__getattribute__(modules[module], '__dict__')
                value = (parser_type if module == 'argparse' and name == 'ArgumentParser'
                         else _DICT.__getitem__(namespace, name))
            elif operation == 'item':
                if _TYPE(value) is not _TUPLE:
                    raise ValueError('shared parser tuple layout changed')
                value = _TUPLE.__getitem__(value, operand)
            elif operation == 'function-code':
                if _TYPE(value) is not _FUNCTION:
                    raise ValueError('shared parser function layout changed')
                value = _OBJECT.__getattribute__(value, '__code__')
            elif operation == 'function-defaults':
                if _TYPE(value) is not _FUNCTION:
                    raise ValueError('shared parser defaults layout changed')
                value = _OBJECT.__getattribute__(value, '__defaults__')
            elif operation == 'code-consts':
                if _TYPE(value) is not _CODE:
                    raise ValueError('shared parser code layout changed')
                value = _OBJECT.__getattribute__(value, 'co_consts')
            elif operation == 'class-item':
                if _TYPE(value) is not _TYPE:
                    raise ValueError('shared parser class metatype changed')
                value = _TYPE.__getattribute__(value, '__dict__')[operand]
            elif operation == 'schema-key':
                mapping = types.ModuleType.__getattribute__(hia_schema, '__dict__')['PRIMITIVE_PROFILES']
                if _TYPE(mapping) is not types.MappingProxyType:
                    raise ValueError('shared parser schema registry changed')
                value = _TUPLE(mapping)[operand]
            else:
                raise ValueError('unknown shared physical path operation')
        if definition_sha(value) != signature:
            raise ValueError('shared parser definition differs from the admitted graph')
        result.append(value)
    return _TUPLE(result)


class PhysicalObjects:
    def __init__(self, shared, node_count, version, original_input):
        self.shared = shared
        self.handles = [_EMPTY] * (node_count + 1)
        self.version = version
        self.original_input = original_input

    def get(self, index):
        if _TYPE(index) is not _INT or not 0 <= index < len(self.handles):
            raise RuntimeError('parser object handle outside its arena')
        value = self.handles[index]
        if value is _EMPTY:
            raise RuntimeError('parser object handle is absent or consumed')
        return value

    def take(self, index):
        value = self.get(index)
        self.handles[index] = _EMPTY
        return value

    def put(self, index, value):
        if (_TYPE(index) is not _INT or not 0 <= index < len(self.handles)
                or self.handles[index] is not _EMPTY):
            raise RuntimeError('parser object destination is already occupied')
        self.handles[index] = value

    def effect(self, operation, destination, a, b, payload):
        if operation == 1:
            self.put(destination, {})
        elif operation == 2:
            self.put(destination, [])
        elif operation == 3:
            cls = self.shared[a]
            if _TYPE(cls) is not _TYPE:
                raise RuntimeError('parser object allocator lacks its exact class')
            self.put(destination, _OBJECT.__new__(cls))
        elif operation == 4:
            self.put(destination, self.shared[a])
        elif operation == 5:
            code = self.shared[a]
            if _TYPE(code) is not _CODE:
                raise RuntimeError('parser identity function code layout changed')
            self.put(destination, _FUNCTION(code, vars(argparse)))
        elif operation == 6:
            self.put(destination, self.version)
        elif operation == 7:
            if len(payload) < 3 or struct.unpack_from('<H', payload, 1)[0] != len(payload) - 3:
                raise RuntimeError('invalid parser scalar envelope')
            tag, raw = payload[0], payload[3:]
            if tag == 0 and not raw:
                value = None
            elif tag == 1 and raw in (b'\0', b'\1'):
                value = raw == b'\1'
            elif tag == 2 and len(raw) == 8:
                value = _INT.from_bytes(raw, 'little', signed=True)
            elif tag == 3:
                value = _BYTES.decode(raw, 'utf-8', 'surrogatepass')
            elif tag == 4:
                value = raw
            else:
                raise RuntimeError('unknown parser scalar layout')
            self.put(destination, value)
        elif operation == 8:
            value = self.get(destination)
            if _TYPE(value) is not _LIST:
                raise RuntimeError('parser list link has the wrong physical type')
            _LIST.append(value, self.get(a))
        elif operation == 9:
            value = self.take(destination)
            if _TYPE(value) is not _LIST:
                raise RuntimeError('parser tuple operands have the wrong physical type')
            cls = _TUPLE if a == 65535 else self.shared[a]
            self.put(destination, _TUPLE.__new__(cls, value))
        elif operation == 10:
            self.put(destination, re.compile(self.get(a), self.get(b)))
        elif operation == 11:
            target = self.get(destination)
            if _TYPE(target) is not _DICT:
                raise RuntimeError('parser dict link has the wrong physical type')
            _DICT.__setitem__(target, self.get(a), self.get(b))
        elif operation == 12:
            target, namespace = self.get(destination), self.get(a)
            if _TYPE(namespace) is not _DICT or _TYPE(_TYPE(target)) is not _TYPE:
                raise RuntimeError('parser object dictionary layout changed')
            _OBJECT.__setattr__(target, '__dict__', namespace)
        elif operation == 13:
            self.take(destination)
        elif operation == 14:
            if a % 4 or a > len(self.original_input) or b > (len(self.original_input) - a) // 4:
                raise RuntimeError('parser error string span left its retained input')
            self.put(destination, self.original_input[a:a+b*4].decode('utf-32-le', 'surrogatepass'))
        else:
            raise RuntimeError('unknown physical parser object instruction')
